{
  "name": "behavior-harness",
  "version": "2.1.3",
  "description": "BehaviorHarness — OpenCode plugin + MCP server that enforces agent workflow gates (preflight, domain-check, prohibited-check, verify)",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": {
      "import": "./dist/index.js"
    }
  },
  "bin": {
    "behavior-harness": "dist/server.js"
  },
  "scripts": {
    "build": "tsup",
    "build:plugin": "tsup --config tsup.config.ts -- index.ts",
    "build:mcp": "tsup --config tsup.config.ts -- server.ts",
    "start": "node dist/server.js",
    "prepublishOnly": "tsup"
  },
  "files": [
    "dist/",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "node": ">=18"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.4.3"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    }
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.12.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.17.9",
    "@types/node": "^22.0.0",
    "tsup": "^8.5.1",
    "typescript": "^5.8.0"
  },
  "keywords": [
    "mcp",
    "ag-kit",
    "harness",
    "agents",
    "opencode",
    "opencode-plugin",
    "behavioral-gates",
    "workflow"
  ],
  "author": "rennanbastosc <rennan.bastosc@gmail.com>",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/rennanbastosc-source/chatbotrdo.git",
    "directory": ".agents/harness"
  },
  "homepage": "https://github.com/rennanbastosc-source/chatbotrdo/tree/master/.agents/harness#readme",
  "bugs": {
    "url": "https://github.com/rennanbastosc-source/chatbotrdo/issues"
  },
  "publishConfig": {
    "access": "public"
  }
}
